import java.util.*;
public class RiverBendFairingTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static double turn(List<RiverRibbon.Point> ps){double max=0;for(int i=1;i<ps.size()-1;i++){var a=ps.get(i-1);var b=ps.get(i);var c=ps.get(i+1);double ax=b.x()-a.x(),az=b.z()-a.z(),bx=c.x()-b.x(),bz=c.z()-b.z();if(Math.hypot(ax,az)<.01||Math.hypot(bx,bz)<.01)continue;max=Math.max(max,Math.abs(Math.atan2(ax*bz-az*bx,ax*bx+az*bz)));}return max;}
 public static void main(String[] args){
  var path=new ArrayList<RiverRibbon.Point>();for(int x=100;x<=900;x+=4)path.add(new RiverRibbon.Point(x,500+50*Math.sin((x-100)*Math.PI*2/400)+12*Math.sin((x-100)*Math.PI*2/24),8,100-(x-100)*.01,1000+x));
  float[] flat=EnvironmentMap.filled(256*256,98);var clean=RiverBendFairing.smooth(path,flat,256,4);double before=turn(path),after=turn(clean);check(after<before*.25&&after<.2,"short wiggles remain: "+before+" -> "+after);check(clean.get(0).equals(path.get(0))&&clean.get(clean.size()-1).equals(path.get(path.size()-1)),"fixed source and outlet");double min=9999,max=-9999;for(var p:clean){min=Math.min(min,p.z());max=Math.max(max,p.z());}check(max-min>55,"broad bends retained");
  var corner=new ArrayList<RiverRibbon.Point>();for(int x=100;x<=500;x+=4)corner.add(new RiverRibbon.Point(x,300,10,100));for(int z=304;z<=700;z+=4)corner.add(new RiverRibbon.Point(500,z,10,100));var rounded=RiverBendFairing.smooth(corner,flat,256,4);check(turn(rounded)<.2,"sharp elbow remains");double setback=rounded.stream().mapToDouble(p->Math.hypot(p.x()-500,p.z()-300)).min().orElse(0);check(setback>12,"bend radius too tight");
  var ridge=flat.clone();for(int z=0;z<256;z++)for(int x=0;x<256;x++)if(Math.hypot(x*4-480,z*4-320)<12)ridge[z*256+x]=180;var guarded=RiverBendFairing.smooth(corner,ridge,256,4);for(int i=1;i<guarded.size();i++)for(int j=0;j<=8;j++){var p=RiverRibbon.lerp(guarded.get(i-1),guarded.get(i),j/8.);check(RiverShape.height(ridge,256,p.x()/4,p.z()/4)<120,"fairing cuts through protected ridge");}
  var parent=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(new RiverRibbon.Point(100,600,10,100),new RiverRibbon.Point(900,600,10,100),3)));var incoming=new ArrayList<RiverRibbon.Point>();for(int z=200;z<=600;z+=4)incoming.add(new RiverRibbon.Point(400,z,8,100));var merge=RiverConfluenceCurve.smooth(incoming,parent,flat,256,4);var tip=merge.get(merge.size()-1);var previous=merge.get(merge.size()-2);check(tip.x()>400&&tip.z()==600,"merge ends downstream on receiver");check((tip.x()-previous.x())/Math.hypot(tip.x()-previous.x(),tip.z()-previous.z())>.98,"merge follows receiving tangent");check(turn(merge)<.2,"sharp confluence approach");var combined=new ArrayList<>(parent.segments);for(int i=1;i<merge.size();i++)combined.add(new RiverRibbon.Segment(merge.get(i-1),merge.get(i),3));check(RiverCrossingAudit.count(new RiverRibbon.Network(combined))==0,"curved confluence avoids crossings");
  for(int i=1;i<clean.size();i++)check(clean.get(i).water()<=clean.get(i-1).water(),"downhill water metadata retained");check(clean.equals(RiverBendFairing.smooth(path,flat,256,4)),"deterministic fairing");
  System.out.println("PASS short-wave turn reduced "+Math.toDegrees(before)+" -> "+Math.toDegrees(after)+" degrees; broad bends retained; elbow setback "+setback+" blocks; endpoints and water retained");
 }
}
